pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // Admissible domain: feeRate must be <= 5000 per require statement.
        vm.assume(_feeRate <= 5000);

        // Initialize the contract with the fuzzed fee rate
        c.initialize(
            address(0), // _baseToken
            address(0), // _nft
            1e18, // _virtualBaseTokenReserves
            1e18, // _virtualNftReserves
            0, // _changeFee
            _feeRate,
            bytes32(0), // _merkleRoot
            false, // _useStolenNftOracle
            false  // _payRoyalties
        );

        // Assert: the stored feeRate must equal the input _feeRate (the reference rule),
        // but the buggy version stores _feeRate % 100, breaking this for _feeRate >= 100.
        assertEq(c.feeRate(), _feeRate);
    }
}

